        return float('inf') if x2 == x1 else (y2 - y1) / (x2 - x1)

    if N <= 2:
        return "success"

    slopes = set()
    for i in range(N):
        for j in range(i + 1, N):
            slopes.add(slope(targets[i][0], targets[i][1], targets[j][0], targets[j][1]))

